 ?><section class="panel ess-welcome"><div><h2>Hello, <?=h($user['name'])?></h2><p><?=h(date('l, j F Y'))?> · <?=h(date_default_timezone_get())?></p><strong data-ess-clock data-time="<?=time()*1000?>" data-zone="<?=h(date_default_timezone_get())?>"><?=h(date('H:i:s'))?></strong></div><div><span class="badge"><?=h($current['status']??'No attendance')?></span><p>Shift: <?=h($shift['title']??'Not assigned')?></p><p>Check in: <?=h($current['check_in']??'—')?> · Check out: <?=h($current['check_out']??'—')?></p><?php if(att_ready($pdo)&&!empty(att_config($pdo)['web_punch_enabled'])):?><form method="post"><?php token();?><input type="hidden" name="action" value="ess_punch"><input type="hidden" name="request_key" value="<?=bin2hex(random_bytes(32))?>"><button class="primary" name="punch_action" value="Check In">Check In</button><button name="punch_action" value="Check Out">Check Out</button></form><?php else:?><p>Web punches are disabled. Use your configured attendance method.</p><?php endif;?><a href="?page=regularisation">Request a correction</a></div></section><div class="ess-cards"><?php foreach(['Recorded work'=>ess_hours($current['working_minutes']??0),'Overtime'=>ess_hours($current['overtime_minutes']??0),'Scheduled break'=>ess_hours($shift['values']['break_minutes']??0),'Open tasks'=>count(array_filter($tasks,fn($r)=>$r['status']!=='Completed')),'Completed tasks'=>count(array_filter($tasks,fn($r)=>$r['status']==='Completed'))] as $label=>$value):?><section class="panel"><small><?=h($label)?></small><h2><?=h($value)?></h2></section><?php endforeach;?></div><p>Working hours reflect processed attendance. An open punch is finalized after check-out.</p><form method="get" class="panel work-form"><input type="hidden" name="page" value="overview"><label>Overview month<input type="month" name="month" value="<?=h($month)?>" required></label><button class="primary">Apply</button></form><section class="panel"><h2>Leave balance · <?=h(date('Y'))?></h2><?php ess_table(['type'=>'Leave type','available'=>'Available days'],ess_balances($pdo,$owner,(int)date('Y')));?></section><section class="panel"><h2>My monthly attendance</h2><p>Late arrivals: <?=count(array_filter($rows,fn($r)=>$r['late_minutes']>0))?> · Early departures: <?=count(array_filter($rows,fn($r)=>$r['early_minutes']>0))?></p><?php $summary=[];foreach($rows as $r)$summary[$r['status']]=($summary[$r['status']]??0)+1;ess_table(['status'=>'Status','days'=>'Days'],array_map(fn($s)=>['status'=>$s,'days'=>$summary[$s]],array_keys($summary)));?></section><section class="panel ess-calendar"><h2>Company calendar</h2><?php $events=array_values(array_filter(ess_events($pdo,$employee),fn($e)=>$e['end']>=$from&&$e['start']<=$to));ess_table(['title'=>'Event','start'=>'From','end'=>'To','description'=>'Details'],$events);?></section><?php $portal=chr_rows($pdo,'ess_settings')[0]['values']??[];if(!empty($portal['birthdays_enabled'])):$b=$pdo->prepare("SELECT u.name,DATE_FORMAT(e.birth_date,'%d %b') birthday FROM employees e JOIN users u ON u.id=e.user_id WHERE e.deleted_at IS NULL AND u.active=1 AND e.employment_status='Active' AND MONTH(e.birth_date)=? ORDER BY DAY(e.birth_date)");$b->execute([(int)substr($month,5,2)]);?><section class="panel"><h2>Birthdays this month</h2><?php ess_table(['name'=>'Colleague','birthday'=>'Birthday'],$b->fetchAll(PDO::FETCH_ASSOC));?></section><?php endif;?><div class="quick-links"><a href="?page=balances">Leave balance</a><a href="?page=inbox">Open inbox</a><a href="?page=tasks">My tasks</a></div><?php
 }else{?><form method="get" class="panel work-form"><input type="hidden" name="page" value="<?=h($page)?>"><label>Month<input type="month" name="month" value="<?=h($month)?>" required></label><button class="primary">Apply</button></form><section class="panel"><?php foreach($rows as &$r){$r['worked']=ess_hours($r['working_minutes']);$r['late']=ess_hours($r['late_minutes']);$r['early']=ess_hours($r['early_minutes']);$r['overtime']=ess_hours($r['overtime_minutes']);}unset($r);ess_table(['date'=>'Date','shift'=>'Shift','status'=>'Status','check_in'=>'Check in','check_out'=>'Check out','worked'=>'Worked','late'=>'Late arrival','early'=>'Early departure','overtime'=>'Overtime'],$rows);?></section><?php }
