}elseif(in_array($page,['inbox','notifications'],true)){$items=ess_inbox($pdo,$user);$shown=0;foreach($items as $item){if($item['state']==='Archived')continue;$shown++;?><section class="panel"><h2><?=h($item['title'])?></h2><p><?=h($item['text'])?></p><small><?=h($item['at'].' · '.$item['state'])?></small><div class="ess-actions"><a href="?page=<?=h($item['page'])?>">View details</a><form method="post"><?php token();?><input type="hidden" name="action" value="ess_inbox"><input type="hidden" name="key" value="<?=h($item['key'])?>"><button name="state" value="<?=$item['state']==='Unread'?'Read':'Unread'?>">Mark <?=$item['state']==='Unread'?'read':'unread'?></button><button name="state" value="Archived">Archive</button></form></div></section><?php }if(!$shown)echo '<section class="panel ess-empty"><span class="ess-empty-icon" aria-hidden="true">✓</span><h2>You are all caught up</h2><p>Your request updates, task notifications and announcements will appear here.</p><a class="primary" href="?page=overview">Back to dashboard</a></section>';
}elseif($page==='my_salary'){require_once __DIR__.'/../payroll/config.php';?><section class="panel"><h2>My salary</h2><?php if(pay_ready($pdo)){$q=$pdo->prepare('SELECT effective_from,effective_to,monthly_gross,annual_ctc FROM hr_salary_assignments WHERE employee_id=? AND effective_from<=? ORDER BY effective_from DESC LIMIT 1');$q->execute([$owner,$today]);$salary=$q->fetch(PDO::FETCH_ASSOC);if($salary&&(!$salary['effective_to']||$salary['effective_to']>=$today)){$salary['monthly_gross']=number_format($salary['monthly_gross']/100,2);$salary['annual_ctc']=number_format($salary['annual_ctc']/100,2);ess_table(['effective_from'=>'Effective from','monthly_gross'=>'Monthly gross','annual_ctc'=>'Annual CTC'],[$salary]);}else echo '<p>No effective salary assignment is available.</p>';}else echo '<p>Payroll is not configured yet.</p>';?><a href="payroll-slip.php">View my published payslips</a></section><?php }
